import{_ as e,o as t,c as a,a0 as i}from"./chunks/framework.1R7PBCUH.js";const g=JSON.parse('{"title":"Users and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"labs/users-and-permissions.md","filePath":"labs/users-and-permissions.md"}'),o={name:"labs/users-and-permissions.md"};function n(r,s,d,h,p,l){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="users-and-permissions" tabindex="-1">Users and Permissions <a class="header-anchor" href="#users-and-permissions" aria-label="Permalink to &quot;Users and Permissions&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This lab is still in draft. It contains all the information you need, but the text isn&#39;t polished yet.</p></div><p>In this lab, you&#39;ll learn how Linux manages users and controls access to files and directories.</p><p>You&#39;ll learn where user and group information is stored, how to read and change permissions, and how to work with elevated privileges.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>Linux is a multi-user operating system: multiple people can use the same system, either at the same time or one after another. To keep their files separate and secure, the operating system assigns every person a <strong>user account</strong>.</p><p>When you log in, the operating system identifies you by your <strong>user ID (UID)</strong>. This is a unique number assigned to your account. Your username is a human-readable alias for this number. The operating system always works with UIDs internally.</p><p>Use the <strong><code>id</code></strong> command to display your UID and the groups you belong to:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span></span></code></pre></div><p>The output looks similar to this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uid=1000(steven) gid=1000(steven) groups=1000(steven),4(adm),27(sudo)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>uid</td><td>Your user ID and username.</td></tr><tr><td>gid</td><td>Your primary group ID and group name.</td></tr><tr><td>groups</td><td>All groups you belong to, including your primary group.</td></tr></tbody></table><p>You can also look up another user&#39;s UID and groups by passing their username as an argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span></span></code></pre></div><p>Every Linux system has this special user named <strong>root</strong>, also known as the <strong>superuser</strong>, which has a UID of 0. The root user can modify any file on the system, regardless of its permissions.</p><p>Because root is so powerful, any mistake made as root can damage or compromise the entire system. For this reason, it&#39;s best practice to avoid logging in directly as root, which is why we use <code>sudo</code> instead to temporarily elevate our privileges to those of root.</p><h3 id="etc-passwd" tabindex="-1">/etc/passwd <a class="header-anchor" href="#etc-passwd" aria-label="Permalink to &quot;/etc/passwd&quot;">​</a></h3><p>Linux stores user account information in the file <strong>/etc/passwd</strong>. Despite its name, this file does not store passwords. Display its contents:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/passwd</span></span></code></pre></div><p>Each line represents one user account. The fields on each line are separated by colons (<code>:</code>). A typical entry looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>steven:x:1000:1000:Steven:/home/steven:/bin/bash</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Username</td><td><code>steven</code></td><td>The human-readable name for the account.</td></tr><tr><td>Password placeholder</td><td><code>x</code></td><td>Always <code>x</code>; the actual password is stored elsewhere.</td></tr><tr><td>UID</td><td><code>1000</code></td><td>The user ID. UIDs below 1000 are typically reserved for system accounts.</td></tr><tr><td>GID</td><td><code>1000</code></td><td>The primary group ID.</td></tr><tr><td>Comment</td><td><code>Steven</code></td><td>A human-readable description, often the user&#39;s full name.</td></tr><tr><td>Home directory</td><td><code>/home/steven</code></td><td>The path to the user&#39;s home directory.</td></tr><tr><td>Login shell</td><td><code>/bin/bash</code></td><td>The shell that starts when the user logs in.</td></tr></tbody></table><p>You&#39;ll notice many entries that aren&#39;t for real people. These are <strong>service accounts</strong>: user accounts created not for human users, but for system services. A web server, for example, might run under a dedicated <code>www-data</code> account.</p><p>Service accounts exist for security. Running a service under its own account limits the damage if that service is ever compromised. It can only access what its account is permitted to.</p><p>Service accounts typically have <code>/usr/sbin/nologin</code> or <code>/bin/false</code> as their login shell. These are not real shells; they immediately exit when invoked, preventing anyone from logging in as that account interactively.</p><h3 id="etc-shadow" tabindex="-1">/etc/shadow <a class="header-anchor" href="#etc-shadow" aria-label="Permalink to &quot;/etc/shadow&quot;">​</a></h3><p>Passwords are stored in <strong>/etc/shadow</strong>, not in <strong>/etc/passwd</strong>. The reason is simple: <strong>/etc/passwd</strong> must be readable by all users so the system can look up usernames and UIDs. Storing passwords there — even in hashed form — would allow any user to attempt to crack them offline.</p><p><strong>/etc/shadow</strong> is protected: only the root user can read it. Verify this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/shadow</span></span></code></pre></div><p>Try again with <code>sudo</code> to elevate your permissions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/shadow</span></span></code></pre></div><p>Each line in <strong>/etc/shadow</strong> corresponds to a user account in <strong>/etc/passwd</strong> and stores the hashed password alongside information such as when the password was last changed and when it expires.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>A <strong>hash function</strong> transforms a password into a fixed-length string through a non-reversible process. When you log in, the system hashes the password you entered and compares the result to the stored hash. This way, the system can authenticate you without ever needing to store your password.</p></div><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>A <strong>group</strong> is a collection of user accounts. Groups make it practical to share access to resources: instead of managing permissions for each user individually, you add users to a group and assign permissions to that group.</p><p>Every user belongs to at least one group: their <strong>primary group</strong>. This group usually has the same name as its user and is automatically assigned to all files created by this user. Users can also belong to <strong>secondary groups</strong>, which grant access to resources shared by those groups.</p><p>Group information is stored in <strong>/etc/group</strong>. Take a look at its contents:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/group</span></span></code></pre></div><p>Each line represents one group, with fields separated by colons. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo:x:27:steven</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Group name</td><td><code>sudo</code></td><td>The name of the group.</td></tr><tr><td>Password placeholder</td><td><code>x</code></td><td>Groups can have passwords, but this is rarely used.</td></tr><tr><td>GID</td><td><code>27</code></td><td>The group ID.</td></tr><tr><td>Members</td><td><code>steven</code></td><td>A comma-separated list of users for whom this is a secondary group.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Note</p><p>Primary group membership is recorded in <strong>/etc/passwd</strong> (the GID field), not in <strong>/etc/group</strong>. The <strong>/etc/group</strong> file only lists secondary memberships.</p></div><p>Use the <strong><code>groups</code></strong> command to list the groups you belong to:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groups</span></span></code></pre></div><p>You can also check the groups of another user by passing their username:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groups</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span></span></code></pre></div><h2 id="changing-passwords" tabindex="-1">Changing passwords <a class="header-anchor" href="#changing-passwords" aria-label="Permalink to &quot;Changing passwords&quot;">​</a></h2><p>Use the <strong><code>passwd</code></strong> command to change your password:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">passwd</span></span></code></pre></div><p>You will be prompted for your current password, then asked to enter and confirm the new one.</p><p>As root, you can change the password of any user. To try this out, first create a new user named alice:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>Now set an initial password for Alice:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>You can set this password to expire immediately after Alice signs in. She will then be prompted to change her password:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>You can also use <code>passwd</code> to lock a user account, for example, when a user leaves your organization:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>A locked account cannot be logged into, even when a user knows the password. To unlock the account, use the <code>-u</code> option:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Every file and directory has a set of <strong>permissions</strong> that control who can read, modify, or execute it. These permissions are divided into three categories:</p><table tabindex="0"><thead><tr><th>Category</th><th>Symbol</th><th>Description</th></tr></thead><tbody><tr><td>Owner (<em>user</em>)</td><td><code>u</code></td><td>Permissions for the user that owns the file.</td></tr><tr><td>Group</td><td><code>g</code></td><td>Permissions for the group that owns the file.</td></tr><tr><td>Others</td><td><code>o</code></td><td>Permissions for everyone else.</td></tr></tbody></table><p>Each of these categories has three permission bits. The meaning of each bit depends on whether it&#39;s set on a file or on a directory:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Symbol</th><th>On a file</th><th>On a directory</th></tr></thead><tbody><tr><td>Read</td><td><code>r</code></td><td>View the contents of the file.</td><td>List the contents of the directory.</td></tr><tr><td>Write</td><td><code>w</code></td><td>Modify the file.</td><td>Create, rename, or delete files inside the directory.</td></tr><tr><td>Execute</td><td><code>x</code></td><td>Run the file as a program.</td><td>Enter the directory and access its contents.</td></tr></tbody></table><p>Directory permissions can take some getting used to. For example, you cannot <code>cd</code> into a directory without execute permission on that directory, even if you have permission to read the directory. Also, you cannot remove a file from a directory without write permission on the <em>directory</em>, even if you have write permission on the <em>file</em>.</p><h3 id="viewing-permissions" tabindex="-1">Viewing permissions <a class="header-anchor" href="#viewing-permissions" aria-label="Permalink to &quot;Viewing permissions&quot;">​</a></h3><p>Use <code>ls -l</code> to view the permissions of files and directories:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre></div><p>Each line of output starts with a string of ten characters. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-rwxr-xr--</span></span></code></pre></div><p>The first of these characters indicates the <strong>file type</strong>:</p><table tabindex="0"><thead><tr><th>Character</th><th>File type</th></tr></thead><tbody><tr><td><code>-</code></td><td>Regular file</td></tr><tr><td><code>d</code></td><td>Directory</td></tr><tr><td><code>l</code></td><td>Symbolic link</td></tr></tbody></table><p>The remaining nine characters form three groups of three, representing the permissions for the owner, group, and others respectively:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rwx  r-x  r--</span></span>
<span class="line"><span> │    │    └── Others: read only</span></span>
<span class="line"><span> │    └── Group: read and execute</span></span>
<span class="line"><span> └── Owner: read, write, and execute</span></span></code></pre></div><p>Each letter indicates that permission is granted; a dash (<code>-</code>) means it&#39;s not.</p><h3 id="octal-notation" tabindex="-1">Octal notation <a class="header-anchor" href="#octal-notation" aria-label="Permalink to &quot;Octal notation&quot;">​</a></h3><p>Permissions can also be expressed as three-digit octal numbers, with one digit per category (owner, group, and others), ranging from 0 to 7. The value of each digit is the sum of the granted permissions for that category:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Value</th></tr></thead><tbody><tr><td>Read</td><td>4</td></tr><tr><td>Write</td><td>2</td></tr><tr><td>Execute</td><td>1</td></tr></tbody></table><p>For example, the permissions <code>rwxr-xr--</code> correspond with:</p><ul><li>Owner: <code>r</code> + <code>w</code> + <code>x</code> = 4 + 2 + 1 = <strong>7</strong></li><li>Group: <code>r</code> + <code>x</code> = 4 + 1 = <strong>5</strong></li><li>Others: <code>r</code> = <strong>4</strong></li></ul><p>The octal representation of <code>rwxr-xr--</code> is therefore <strong>754</strong>. You can use this octal representation as a shorthand to set all permission bits at once.</p><h3 id="changing-permissions" tabindex="-1">Changing permissions <a class="header-anchor" href="#changing-permissions" aria-label="Permalink to &quot;Changing permissions&quot;">​</a></h3><p>Use the <strong><code>chmod</code></strong> (<em>change mode</em>) command to change the permissions of a file or directory. To try this out, first create a few new files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span></span></code></pre></div><p>The <strong><code>touch</code></strong> command updates the modification time of a file, and as a side effect, also creates the file.</p><p>Use <code>ls -l</code> to view the permissions of these files. By default, they should all be set to <code>rw-rw-r--</code>. You can use either <strong>symbolic notation</strong> or <strong>octal notation</strong> to change these permissions.</p><p>With symbolic notation, you build up a change from three parts: <strong>who</strong>, <strong>what</strong>, and <strong>which</strong>.</p><p>The <strong>who</strong> part specifies the category to change:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Category</th></tr></thead><tbody><tr><td><code>u</code></td><td>Owner (<em>user</em>)</td></tr><tr><td><code>g</code></td><td>Group</td></tr><tr><td><code>o</code></td><td>Others</td></tr><tr><td><code>a</code></td><td>All categories</td></tr></tbody></table><p>The <strong>what</strong> part specifies the operation:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Operation</th></tr></thead><tbody><tr><td><code>+</code></td><td>Add the permission.</td></tr><tr><td><code>-</code></td><td>Remove the permission.</td></tr><tr><td><code>=</code></td><td>Set exactly these permissions, removing any others.</td></tr></tbody></table><p>The <strong>which</strong> part specifies the permissions to change:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Permission</th></tr></thead><tbody><tr><td><code>r</code></td><td>Read</td></tr><tr><td><code>w</code></td><td>Write</td></tr><tr><td><code>x</code></td><td>Execute</td></tr></tbody></table><p>You can specify multiple categories and permissions in a single change, and even specify multiple changes in a single command. For example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ug+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g-w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g-rw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g=r,o=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span></span></code></pre></div><p>Here&#39;s what these example do:</p><ol><li>Add execute permission for the owner on <strong>script.sh</strong>.</li><li>Add execute permission for the owner and group on <strong>script.sh</strong>.</li><li>Add execute permission for all categories on <strong>script.sh</strong>.</li><li>Remove write permission for the group on <strong>report.txt</strong>.</li><li>Remove read and write permissions for the group on <strong>report.txt</strong>.</li><li>Set the group permissions to read-only and remove all permissions for other users on <strong>secret</strong>.</li></ol><p>With octal notation, you set all permission bits at once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span></span></code></pre></div><p>This sets the permissions of <strong>report.txt</strong> to <code>rw-r--r--</code>: read and write for the owner, read-only for the group and others.</p><p>When you&#39;re done experimenting with <code>chmod</code>, clean up the files you created:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span></span></code></pre></div><h3 id="changing-owner-and-group" tabindex="-1">Changing owner and group <a class="header-anchor" href="#changing-owner-and-group" aria-label="Permalink to &quot;Changing owner and group&quot;">​</a></h3><p>As root, you can change the owner and group of a file. To try this out, suppose you want to prepare the lab materials for the new user you created earlier.</p><p>Create a new directory for the lab materials in Alice&#39;s home directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can now unzip and organize the lab materials into this directory, as you did in <a href="./files-and-directories.html#materials">Files and Directories</a>. However, this step is optional because you don&#39;t actually need these files to complete this lab.</p></div><p>Because you used <code>sudo</code>, the <strong>lab-materials</strong> directory is owned by root, not Alice:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ld</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><p>Use the <strong><code>chown</code></strong> (<em>change owner</em>) command to transfer ownership to Alice:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><p>The <code>-R</code> option applies this change recursively to all of the files and subdirectories in <strong>lab-materials</strong>.</p><p>Next, use the <strong><code>chgrp</code></strong> (<em>change group</em>) command to set the group to Alice&#39;s primary group, which is also named <code>alice</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chgrp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><p>Alternatively, you can use <code>chown</code> to change both the owner and the group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice:alice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><p>Confirm these changes with <code>ls</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ld</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><h3 id="default-permissions" tabindex="-1">Default permissions <a class="header-anchor" href="#default-permissions" aria-label="Permalink to &quot;Default permissions&quot;">​</a></h3><p>When you create a new file or directory, Linux assigns it a default set of permissions based on the base set and the current <strong>umask</strong> (<em>user file-creation mask</em>).</p><p>The base permissions are:</p><ul><li><strong>666</strong> (<code>rw-rw-rw-</code>) for files</li><li><strong>777</strong> (<code>rwxrwxrwx</code>) for directories</li></ul><p>This enables all permissions, except for files, which aren&#39;t executable by default.</p><p>The umask specifies the permissions to <em>remove</em> from the base set. Each bit in the umask that is set to 1 removes the corresponding permission from the base set.</p><p>For example, a umask of <strong>022</strong> (<code>----w--w-</code>) removes write permissions for the group and other users. This results in default permissions of <strong>755</strong> (<code>rwxr-xr-x</code>) for directories:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base:     rwxrwxrwx  (777)</span></span>
<span class="line"><span>Mask:     ----w--w-  (022)</span></span>
<span class="line"><span>          ─────────</span></span>
<span class="line"><span>Default:  rwxr-xr-x  (755)</span></span></code></pre></div><p>and <strong>644</strong> (<code>rw-r--r--</code>) for files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base:     rw-rw-rw-  (666)</span></span>
<span class="line"><span>Mask:     ----w--w-  (022)</span></span>
<span class="line"><span>          ─────────</span></span>
<span class="line"><span>Default:  rw-r--r--  (644)</span></span></code></pre></div><p>The <strong><code>umask</code></strong> command displays the current umask:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">umask</span></span></code></pre></div><p>You also use it to set the umask:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">umask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 007</span></span></code></pre></div><p>This value only applies to your current shell session. To make it permanent, add this <code>umask</code> command to your <strong>.bashrc</strong> file.</p><h2 id="switching-users" tabindex="-1">Switching users <a class="header-anchor" href="#switching-users" aria-label="Permalink to &quot;Switching users&quot;">​</a></h2><p>The <strong><code>su</code></strong> (<em>switch user</em>) command starts a new shell session as a different user:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>This prompts for Alice&#39;s password. After authenticating, you&#39;re running commands as Alice. When you&#39;re done, use the <code>exit</code> command to return to your own shell.</p><p>You can add a dash (<code>-</code>) to start a <strong>login shell</strong> instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><p>This will load a fresh environment for Alice, load her settings from <strong>.bashrc</strong>, and start in her home directory. Verify this with <code>pwd</code> and compare it to using <code>su</code> without the dash.</p><p>If you don&#39;t specify a username, <code>su</code> will attempt to sign in as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span></span></code></pre></div><p>However, this won&#39;t work because the root user doesn&#39;t have a password configured. Ubuntu, like many Linux distributions, doesn&#39;t allow signing in as <code>root</code>, which is why we use <code>sudo</code> instead.</p><h2 id="elevated-privileges" tabindex="-1">Elevated privileges <a class="header-anchor" href="#elevated-privileges" aria-label="Permalink to &quot;Elevated privileges&quot;">​</a></h2><p>The <strong><code>sudo</code></strong> (<em>switch user and do</em> or <em>superuser do</em>) command lets an authorized user run a single command with elevated privileges, typically as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>This approach is safer than signing in as root because you only gain elevated privileges for a single command, you authenticate with your own password rather than the root password, and every <code>sudo</code> command is logged.</p><p>Use the <code>-u</code> option to run a command as a user other than root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/alice/lab-materials</span></span></code></pre></div><p>This is particularly useful when creating files or directories, as it avoids having to transfer ownership afterwards.</p><p>Finally, you can also use <code>sudo</code> to start an interactive (<code>-i</code>) login shell, where you can run multiple commands as a different user:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span></span></code></pre></div><p>This is similar to using <code>su</code>, but <code>sudo</code> does allow signing in as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span></span></code></pre></div><p>This is slightly safer than <code>su</code> because it doesn&#39;t require a root password. However, it remains risky because, as root, every mistake you make can effect the entire system.</p><h3 id="the-sudo-group" tabindex="-1">The sudo group <a class="header-anchor" href="#the-sudo-group" aria-label="Permalink to &quot;The sudo group&quot;">​</a></h3><p>Not every user is allowed to use <code>sudo</code>. Most Linux distributions configure a dedicated group whose members are authorized to use <code>sudo</code>. On Ubuntu, this group is named <strong>sudo</strong>. On some other systems, it&#39;s named <strong>wheel</strong>.</p><p>Use the <code>groups</code> command to verify that you belong to this group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groups</span></span></code></pre></div><p>Or use <code>grep</code> to see everyone in the sudo group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/group</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>In <a href="./../exercises/exercises1.html#user">Exercise 1.4</a>, you used the desktop environment to create a new user account. The panel where you configured this user had an “Administrator” toggle. This toggle adds the user to the sudo group.</p></div><h2 id="up-next" tabindex="-1">Up next <a class="header-anchor" href="#up-next" aria-label="Permalink to &quot;Up next&quot;">​</a></h2><p>In this lab, you learned how Linux organizes users and groups and how it controls access to files and directories through permissions. Practice what you&#39;ve learned by solving the upcoming exercises.</p><p>When you&#39;re done, proceed to the next lab, where you&#39;ll learn how the operating system runs applications.</p>`,166)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
